with up as (update public.artists a set spotify=x.u from json_to_recordset('[{"s":"kumail","u":"https://open.spotify.com/artist/2JYgvhoagKBhBYkpD0gIKj"},{"s":"daisho","u":"https://open.spotify.com/artist/7bdFWpOgq273QGFyfJ1XKd"},{"s":"kumail","u":"https://open.spotify.com/artist/2JYgvhoagKBhBYkpD0gIKj"},{"s":"delhi-sultanate","u":"https://open.spotify.com/artist/6H3noR4Ft24LdJTXGyZI75"}]'::json) as x(s text,u text) where a.slug=x.s and (a.spotify is null or a.spotify='') returning 1) select count(*) from up;